import json, collections, re, csv
wl=json.load(open('watchlist.json'))
def isar(s): return any(0x600<=ord(c)<=0x6ff for c in s)
def iscy(s): return any(0x400<=ord(c)<=0x4ff for c in s)
ar_tokens=collections.Counter(); cy_tokens=collections.Counter()
pairs_ar=[]; pairs_cy=[]
only_ar=collections.Counter(); only_cy=collections.Counter()
for e in wl:
    sn=e['script_name']; pn=e['primary_name']
    lat=[n for n in [pn]+[a['name'] for a in e['aliases'] if a['strength']=='strong'] if re.search('[A-Za-z]',n)]
    if sn and isar(sn):
        for t in sn.split(): ar_tokens[t]+=[REDACTED]
        if lat: pairs_ar.append((sn,lat))
        else:
            for t in sn.split(): only_ar[t]+=[REDACTED]
    if sn and iscy(sn):
        for t in sn.split(): cy_tokens[t]+=[REDACTED]
        if lat: pairs_cy.append((sn,lat))
        else:
            for t in sn.split(): only_cy[t]+=[REDACTED]
print('arabic distinct tokens', len(ar_tokens), 'no-latin entries', len([[REDACTED] for e in wl if e['script_name'] and isar(e['script_name']) and not re.search('[A-Za-z]',e['primary_name'])]))
print('cyr distinct tokens', len(cy_tokens))
print('AR tokens only in script-only entries:', len([t for t in only_ar if t not in {x for s,l in pairs_ar for x in s.split()}]))
print('CY tokens only in script-only entries:', len([t for t in only_cy if t not in {x for s,l in pairs_cy for x in s.split()}]))
print('--- sample ar pairs')
for s,l in pairs_ar[:[REDACTED]5]: print(s,'|',l)
print('--- sample cy pairs')
for s,l in pairs_cy[:[REDACTED]5]: print(s,'|',l)
print('--- ar tokens', sorted(ar_tokens))
print('--- cy tokens', sorted(cy_tokens))
